                        <h6 class="card-subtitle mb-2 text-muted">@shipment.Description</h6>
                        <p class="card-text">
                            <strong>To:</strong> @shipment.Destination<br />
                            <strong>Status:</strong>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span><br />
                            <strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")
                        </p>
                    </div>
                </div>
            </div>
        }
    </div>
}

